#[macro_export]
macro_rules! println {
    () => ($crate::serial::_print("\n"));
    ($($arg:tt)*) => ($crate::serial::_print(&format_args!("{}\n", format_args!($($arg)*))));
}

#[macro_export]
macro_rules! print {
    ($($arg:tt)*) => ($crate::serial::_print(&format_args!($($arg)*)));
}

pub fn _print(args: &core::fmt::Arguments) {
    use core::fmt::Write;
    SERIAL.lock().write_fmt(*args).unwrap();
}

