mod tests {
    use super::*;

    #[test]
    fn test_allocate_page() {
        unsafe {
            let mut mgr = PhysicalMemoryManager::new(0x1000);
            let addr = mgr.allocate_page();
            assert!(addr.is_some());
        }
    }
}

