// FreeLang OS Kernel - Phase G: Bare-Metal 구현
// 실제 x86-64 하드웨어에서 부팅되는 OS

#![no_std]
#![no_main]
#![feature(asm_const)]
#![feature(allocator_api)]

extern crate alloc;

use core::fmt::Write;
use core::panic::PanicInfo;

mod serial;
mod vga_buffer;
mod memory;
mod gdt;
mod interrupts;
mod paging;
mod demand_paging;
mod allocator;

use vga_buffer::WRITER;
