// 키보드 드라이버
// Phase 4: PS/2 키보드 입력 처리

use crate::io::IOPort;
use alloc::vec::Vec;
use spin::Mutex;
use lazy_static::lazy_static;

extern crate alloc;

/// 키보드 포트 (PS/2)
const KEYBOARD_DATA_PORT: u16 = 0x60;
const KEYBOARD_STATUS_PORT: u16 = 0x64;

/// 키보드 상태 플래그
const KB_OUTPUT_FULL: u8 = 0x01;  // 출력 버퍼에 데이터 있음
const KB_INPUT_FULL: u8 = 0x02;   // 입력 버퍼가 가득 참

/// PS/2 키보드 스캔 코드 → ASCII 변환
pub struct KeyboardDriver {
    data_port: IOPort,
    status_port: IOPort,
    shift_pressed: bool,
    ctrl_pressed: bool,
    alt_pressed: bool,
    input_buffer: Vec<u8>,
}

impl KeyboardDriver {
    /// 새 키보드 드라이버 생성
    pub fn new() -> Self {
        KeyboardDriver {
            data_port: IOPort::new(KEYBOARD_DATA_PORT),
            status_port: IOPort::new(KEYBOARD_STATUS_PORT),
            shift_pressed: false,
            ctrl_pressed: false,
            alt_pressed: false,
            input_buffer: Vec::new(),
        }
    }

    /// 키보드 초기화
    pub fn init(&mut self) {
        // PS/2 컨트롤러 활성화 (기본 설정)
        crate::println!("🔧 PS/2 Keyboard initialized");
    }

    /// 키보드 인터럽트 처리
