                   op.value == "rsp" || op.value == "rbp" ||
                   op.value == "rsi" || op.value == "rdi") {
          w = 1  // 64-bit 연산
          needsREX = true
        }
      }
    }

    if (!needsREX) {
      return ""
    }

    // REX byte: 0100_wrxb
    let rex = 0x40 | (w << 3) | (r << 2) | (x << 1) | b
    return toHex(rex, 2)
  }

  // ModR/M 바이트 인코딩
