@media (max-width: 768px) {
    .nav-menu {
        display: none;
        flex-direction: column;
        position: absolute;
        top: 70px;
        left: 0;
        right: 0;
        background: var(--bg-dark);
        border-bottom: 1px solid var(--border);
        gap: 0;
        padding: 20px 0;
    }

    .nav-menu.active {
        display: flex;
    }

    .nav-link {
        display: block;
        padding: 12px 20px;
        text-align: left;
    }

    .menu-toggle {
        display: flex;
    }

    .hero .container {
        grid-template-columns: 1fr;
        gap: 40px;
    }

    .hero-content h1 {
        font-size: 36px;
    }

    .hero-stats {
        grid-template-columns: 1fr;
    }

    .features-grid {
        grid-template-columns: 1fr;
    }

    .about-content {
        grid-template-columns: 1fr;
        gap: 40px;
    }

    .code-showcase {
        grid-template-columns: 1fr;
    }

    .download-options {
        grid-template-columns: 1fr;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .footer-content {
        grid-template-columns: 1fr;
    }

    .hero-buttons {
        flex-direction: column;
    }

    .btn {
        width: 100%;
        text-align: center;
    }
}

@media (max-width: 480px) {
    .hero-content h1 {
        font-size: 28px;
    }

    .features h2,
    .about h2,
    .code-example h2,
    .download h2,
    .contact h2 {
        font-size: 32px;
    }

    .feature-card,
    .stat {
        padding: 20px;
    }

    pre {
        padding: 12px;
    }

    code {
        font-size: 12px;
    }
}

