    background: rgba(26, 35, 50, 0.8);
}

.os-icon {
    margin-bottom: 20px;
    display: flex;
    justify-content: center;
}

.download-card h3 {
    font-size: 20px;
    margin-bottom: 10px;
    color: var(--primary);
}

.download-card p {
    color: var(--text-secondary);
    margin-bottom: 20px;
    font-size: 14px;
}

.copy-hint {
    display: block;
    color: var(--primary);
    font-size: 12px;
    margin-top: 8px;
}

.install-guide {
    background: rgba(26, 35, 50, 0.5);
    border: 1px solid var(--border);
    padding: 40px;
    border-radius: 12px;
}

.install-guide h3 {
    color: var(--primary);
    margin-bottom: 20px;
}

.install-guide ol {
    color: var(--text-secondary);
    padding-left: 30px;
    line-height: 2;
}

.install-guide code {
    background: rgba(0, 0, 0, 0.3);
    padding: 2px 6px;
    border-radius: 4px;
    color: var(--primary);
}

/* Contact Section */
.contact {
    padding: 100px 0;
    background: var(--bg-dark);
}

.contact h2 {
    text-align: center;
    font-size: 44px;
    margin-bottom: 60px;
    background: linear-gradient(135deg, var(--primary) 0%, #00f0ff 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.contact-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 40px;
    margin-bottom: 60px;
}

.contact-item {
    text-align: center;
}

.contact-icon {
    display: flex;
    justify-content: center;
    margin-bottom: 20px;
}

.contact-item h4 {
    color: var(--primary);
    margin-bottom: 10px;
}

.contact-item a {
    color: var(--text-secondary);
    text-decoration: none;
    transition: color 0.3s ease;
}

.contact-item a:hover {
    color: var(--primary);
}

.newsletter {
    background: rgba(26, 35, 50, 0.5);
    border: 1px solid var(--border);
    padding: 40px;
    border-radius: 12px;
    text-align: center;
}

.newsletter h3 {
    color: var(--primary);
    margin-bottom: 10px;
}

.newsletter p {
    color: var(--text-secondary);
    margin-bottom: 20px;
}

.newsletter-form {
    display: flex;
    gap: 10px;
    max-width: 500px;
    margin: 0 auto;
}

.newsletter-form input {
    flex: 1;
    padding: 12px 16px;
    border: 1px solid var(--border);
    background: rgba(0, 0, 0, 0.3);
    color: var(--text-primary);
    border-radius: 6px;
    font-family: inherit;
}

.newsletter-form input::placeholder {
    color: var(--text-secondary);
}

.newsletter-form input:focus {
    outline: none;
    border-color: var(--primary);
}

/* Footer */
.footer {
    background: rgba(0, 0, 0, 0.5);
    border-top: 1px solid var(--border);
    padding: 60px 0 20px;
    color: var(--text-secondary);
}

.footer-content {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 40px;
    margin-bottom: 40px;
}

.footer-section h4 {
    color: var(--primary);
    margin-bottom: 15px;
}

.footer-section ul {
    list-style: none;
}

.footer-section ul li {
    margin-bottom: 10px;
}

.footer-section a {
    color: var(--text-secondary);
    text-decoration: none;
    transition: color 0.3s ease;
}

.footer-section a:hover {
    color: var(--primary);
}

.footer-bottom {
    text-align: center;
    padding-top: 20px;
    border-top: 1px solid var(--border);
    font-size: 14px;
}

/* Responsive Design */
@media (max-width: 768px) {
    .nav-menu {
        display: none;
        flex-direction: column;
        position: absolute;
        top: 70px;
        left: 0;
        right: 0;
        background: var(--bg-dark);
        border-bottom: 1px solid var(--border);
        gap: 0;
        padding: 20px 0;
    }

    .nav-menu.active {
        display: flex;
    }

    .nav-link {
        display: block;
        padding: 12px 20px;
        text-align: left;
    }

    .menu-toggle {
        display: flex;
    }

    .hero .container {
        grid-template-columns: 1fr;
        gap: 40px;
    }

    .hero-content h1 {
        font-size: 36px;
    }

    .hero-stats {
        grid-template-columns: 1fr;
    }

    .features-grid {
        grid-template-columns: 1fr;
    }

    .about-content {
        grid-template-columns: 1fr;
        gap: 40px;
    }

    .code-showcase {
        grid-template-columns: 1fr;
    }

    .download-options {
        grid-template-columns: 1fr;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .footer-content {
        grid-template-columns: 1fr;
    }

    .hero-buttons {
        flex-direction: column;
    }

    .btn {
        width: 100%;
        text-align: center;
    }
}

@media (max-width: 480px) {
    .hero-content h1 {
        font-size: 28px;
    }

    .features h2,
    .about h2,
    .code-example h2,
    .download h2,
    .contact h2 {
        font-size: 32px;
    }

    .feature-card,
    .stat {
        padding: 20px;
    }

    pre {
        padding: 12px;
    }

    code {
        font-size: 12px;
    }
}

