// FreeLang Official Website - JavaScript (외부 의존성 제로)

// 모바일 메뉴 토글
document.addEventListener('DOMContentLoaded', function() {
    const menuToggle = document.getElementById('menuToggle');
    const navMenu = document.getElementById('navMenu');

    if (menuToggle && navMenu) {
        menuToggle.addEventListener('click', function() {
            navMenu.classList.toggle('active');

            // 햄버거 아이콘 애니메이션
            const spans = this.querySelectorAll('span');
            if (navMenu.classList.contains('active')) {
                spans[0].style.transform = 'rotate(45deg) translate(10px, 10px)';
                spans[1].style.opacity = '0';
                spans[2].style.transform = 'rotate(-45deg) translate(7px, -7px)';
            } else {
                spans[0].style.transform = '';
                spans[1].style.opacity = '1';
                spans[2].style.transform = '';
            }
        });

        // 네비게이션 링크 클릭 시 메뉴 닫기
        const navLinks = navMenu.querySelectorAll('.nav-link');
        navLinks.forEach(link => {
            link.addEventListener('click', function() {
                navMenu.classList.remove('active');
                const spans = menuToggle.querySelectorAll('span');
                spans[0].style.transform = '';
                spans[1].style.opacity = '1';
                spans[2].style.transform = '';
            });
        });
    }
});

// 명령어 복사 기능
function copyCommand(command) {
    // 임시 textarea 생성
    const textarea = document.createElement('textarea');
    textarea.value = command;
    document.body.appendChild(textarea);
    textarea.select();

    try {
        document.execCommand('copy');

        // 피드백 표시
        const button = event.target;
        const hint = button.nextElementSibling;
        if (hint) {
            hint.style.display = 'inline';
            setTimeout(() => {
                hint.style.display = 'none';
            }, 2000);
        }

        // 버튼 피드백
        const originalText = button.textContent;
        button.textContent = '복사됨!';
        button.style.background = 'var(--primary)';
        button.style.color = '#000';

        setTimeout(() => {
            button.textContent = originalText;
            button.style.background = '';
            button.style.color = '';
        }, 2000);
    } catch (err) {
        console.error('복사 실패:', err);
        alert('복사에 실패했습니다. 수동으로 복사해주세요: ' + command);
    }

    document.body.removeChild(textarea);
}

// 뉴스레터 구독 처리
function handleNewsletterSubmit(event) {
    event.preventDefault();

    const form = event.target;
    const email = form.querySelector('input[type="email"]').value;
    const button = form.querySelector('button');

    // 이메일 유효성 검사
    if (!isValidEmail(email)) {
        alert('유효한 이메일 주소를 입력해주세요.');
        return;
    }

    // 버튼 상태 변경
    const originalText = button.textContent;
    button.textContent = '구독 중...';
    button.disabled = true;

    // 실제 구현에서는 서버로 전송
    setTimeout(() => {
        button.textContent = '구독됨!';
        button.style.background = 'var(--primary)';
        button.style.color = '#000';
        form.reset();

        setTimeout(() => {
            button.textContent = originalText;
            button.disabled = false;
            button.style.background = '';
            button.style.color = '';
        }, 2000);
    }, 1000);
}

// 이메일 유효성 검사
function isValidEmail(email) {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
}

// 페이지 로드 시 애니메이션
window.addEventListener('load', function() {
    // 모든 카드 요소에 페이드인 애니메이션 추가
    const cards = document.querySelectorAll('.feature-card, .download-card, .contact-item');
    cards.forEach((card, index) => {
        card.style.opacity = '0';
        card.style.animation = `fadeInUp 0.6s ease forwards`;
        card.style.animationDelay = `${index * 0.1}s`;
    });
});

// 스크롤 시 네비게이션 스타일 변경
window.addEventListener('scroll', function() {
    const navbar = document.querySelector('.navbar');
    if (window.scrollY > 50) {
        navbar.style.borderBottomColor = 'rgba(42, 63, 95, 0.5)';
    } else {
        navbar.style.borderBottomColor = 'rgba(42, 63, 95, 1)';
    }
});

// 서비스 워커 등록 (오프라인 지원)
if ('serviceWorker' in navigator) {
    navigator.serviceWorker.register('sw.js').catch(error => {
        console.log('서비스 워커 등록 실패:', error);
    });
}

// 애니메이션 정의 (CSS-in-JS로 필요시 추가)
const style = document.createElement('style');
style.textContent = `
    @keyframes fadeInUp {
        from {
            opacity: 0;
            transform: translateY(30px);
        }
        to {
            opacity: 1;
            transform: translateY(0);
        }
    }

    @keyframes slideInRight {
        from {
            opacity: 0;
            transform: translateX(-30px);
        }
        to {
            opacity: 1;
            transform: translateX(0);
        }
    }

    @keyframes pulse {
        0%, 100% {
            opacity: 1;
        }
        50% {
            opacity: 0.5;
        }
    }
`;
document.head.appendChild(style);

// 접근성 개선: 키보드 네비게이션
document.addEventListener('keydown', function(event) {
    if (event.key === 'Escape') {
        const navMenu = document.getElementById('navMenu');
        if (navMenu && navMenu.classList.contains('active')) {
            navMenu.classList.remove('active');
        }
    }

    // Alt + S: 검색창 포커스 (향후 추가 기능)
    if (event.altKey && event.key === 's') {
        event.preventDefault();
        // 검색 기능 구현
    }
});

// 성능 모니터링
window.addEventListener('load', function() {
    if (window.performance && window.performance.timing) {
        const perfData = window.performance.timing;
        const pageLoadTime = perfData.loadEventEnd - perfData.navigationStart;
        console.log('페이지 로드 시간: ' + pageLoadTime + 'ms');
    }
});

// 동적 다크/라이트 모드 (선택적)
function toggleTheme() {
    const root = document.documentElement;
    const currentTheme = root.style.colorScheme;

    if (currentTheme === 'dark' || !currentTheme) {
        root.style.colorScheme = 'light';
        localStorage.setItem('theme', 'light');
    } else {
        root.style.colorScheme = 'dark';
        localStorage.setItem('theme', 'dark');
    }
}

// 로컬 스토리지에서 테마 복원
window.addEventListener('DOMContentLoaded', function() {
    const savedTheme = localStorage.getItem('theme') || 'dark';
    document.documentElement.style.colorScheme = savedTheme;
});

// 사용자 인터랙션 추적 (분석용)
const eventTracker = {
    events: [],

    track: function(eventName, eventData) {
        this.events.push({
            name: eventName,
            data: eventData,
            timestamp: new Date().toISOString()
        });
    },

    getEvents: function() {
        return this.events;
    }
};

// 버튼 클릭 추적
document.addEventListener('click', function(event) {
    if (event.target.classList.contains('btn')) {
        eventTracker.track('button_click', {
            button: event.target.textContent,
            className: event.target.className
        });
    }
});

// 링크 클릭 추적
document.addEventListener('click', function(event) {
    if (event.target.tagName === 'A' && event.target.href) {
        eventTracker.track('link_click', {
            href: event.target.href,
            text: event.target.textContent
        });
    }
});

// 스크롤 깊이 추적
let maxScroll = 0;
window.addEventListener('scroll', function() {
    const scrollPercentage = (window.scrollY / (document.documentElement.scrollHeight - window.innerHeight)) * 100;
    if (scrollPercentage > maxScroll) {
        maxScroll = scrollPercentage;
    }
});

// 페이지 언로드 시 데이터 저장
window.addEventListener('beforeunload', function() {
    eventTracker.track('page_exit', {
        maxScroll: maxScroll,
        totalEvents: eventTracker.events.length
    });

    // 로컬 스토리지에 이벤트 저장 (선택적)
    try {
        localStorage.setItem('lastVisit', JSON.stringify({
            timestamp: new Date().toISOString(),
            scrollDepth: maxScroll,
            eventCount: eventTracker.events.length
        }));
    } catch (e) {
        console.log('로컬 스토리지 저장 실패:', e);
    }
});

// 외부 링크에 아이콘 추가 (선택적)
document.addEventListener('DOMContentLoaded', function() {
    const externalLinks = document.querySelectorAll('a[target="_blank"]');
    externalLinks.forEach(link => {
        link.title = '새 창에서 열기';
    });
});

console.log('FreeLang 홈페이지 준비 완료 ✨');

