    println("===================================\n")
  }

  // 내보내기
  export {
    addRelocation,
    processRelocations,
    validateRelocations,
    createGOTRelocations,
    createPLTRelocations,
    applyRelocations,
    getAllRelocations,
    getProcessedRelocations,
    getStatistics,
    debug
  }
}

